    """Honest /api/subnets source labels for a shared-universe snapshot."""
    from internal.subnets.feed import subnet_feed_meta

    if snap.status == "emergency_registry":
        return {"source": "registry", "sources": ["registry"]}
    rows = list(snap.rows)
