        rows = _get_all_subnets_tao() or []
        netuids: Set[int] = set()
        by_netuid: Dict[int, Dict[str, Any]] = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            netuid = _netuid_of(row)
            if netuid is None:
                continue
            netuids.add(netuid)
            by_netuid[netuid] = dict(row)
        if not netuids:
