MAX_NETUIDS = 200
STALE_GRACE_SECONDS = 172800  # 48h
ROOT_NETUID = 0  # NetworksAdded lists root but get_member_netuids drops it: membership adds it, the probe never reports on it
REFRESH_INTERVAL_SECONDS = 300
