        "membership": receipt,
        "scoring_set_netuids": scoring_set,
        "root_netuid_in_scoring_set": 0 in scoring_set,
        "day": day_block,
        "hour": hour_block,
        "selection_policy": selection_policy,
        "subnet_load_source": subnet_source,
