        SCORE_SNAPSHOT_TIMING_BUILD_SECONDS.set(SCORE_SNAPSHOT_TIMING_BUILD_UNAVAILABLE)
        SCORE_SNAPSHOT_TIMING_PUBLISH_SECONDS.set(_publish_wall_gauge_value({}))
        for horizon in ("day", "hour"):
