    """
    all_subnets = []
    seen_netuids = set()
    started = time.monotonic()
    for page in range(1, MAX_PAGES + 1):
        if time.monotonic() - started > FETCH_DEADLINE_SEC:
            logger.warning("Subnet fetch deadline (%ss) reached on page %d", FETCH_DEADLINE_SEC, page)
            break
        try:
            from internal.http_client import sync_get

            url = f"{API_BASE}?page={page}"
            logger.info("Fetching subnets page %d from %s", page, url)
            headers = {}
            key = os.environ.get("TMC_API_KEY")
            if key:
                headers["Authorization"] = api_key_header(key)
            resp = sync_get(url, timeout=15, headers=headers)
            if resp.status_code != 200:
                logger.warning("API page %d returned %s", page, resp.status_code)
                break

            payload = resp.json()
            if isinstance(payload, dict):
                rows = payload.get("subnets") or payload.get("data") or payload.get("results")
                if rows is None:
                    break
                if not isinstance(rows, list):
                    break
            elif isinstance(payload, list):
                rows = payload
            else:
                break

            if not rows:
                break

            new_count = 0
            for row in rows:
                parsed = _parse_subnet_row(row)
                netuid = parsed.get("netuid")
                if netuid in seen_netuids:
                    continue
                seen_netuids.add(netuid)
                all_subnets.append(parsed)
                new_count += 1

            logger.info("Page %d: %d new / %d parsed (total unique: %d)", page, new_count, len(rows), len(all_subnets))

            if new_count == 0:
                logger.info("No new subnets on page %d; stopping pagination", page)
                break

            if len(rows) < PAGE_SIZE:
                break

            if page < MAX_PAGES and time.monotonic() - started < FETCH_DEADLINE_SEC:
                time.sleep(1)
        except Exception as e:
            logger.warning("Error fetching page %d: %s", page, e)
            break

    deduped = {}
    for s in all_subnets:
        deduped.setdefault(s.get("netuid"), s)
    all_subnets = list(deduped.values())

    if all_subnets:
        logger.info("Fetched %d unique subnets across all pages", len(all_subnets))
        return all_subnets
    return None

def _rows_have_market_fields(rows: List[Dict]) -> bool:
    """True when a majority of sampled tradable rows carry a live price.

    Registry-only snapshots (no price/volume) must not block TaoMarketCap —
    that short-circuit is what left council picks scoring on bare metadata.
    """
    sample = []
    for r in rows or []:
        n = r.get("netuid")
        if n is None:
            n = r.get("id")
        try:
            if n is not None and int(n) > 0:
                sample.append(r)
        except (TypeError, ValueError):
            continue
        if len(sample) >= 20:
            break
    if not sample:
        return False
    with_price = sum(1 for r in sample if r.get("price") is not None and r.get("price") != "")
    return with_price >= max(1, (len(sample) + 1) // 2)


def _rows_missing_market_values(rows: List[Dict]) -> bool:
    """True when sampled tradable rows already have a price but lack volume/change.

    Live blockmachine rows carry a live price yet leave ``volume`` and the
    ``price_change_*`` fields None. That price-passing state must not skip the
    TMC overlay, or market-driver cards / the weighing room show 0.0/None
    volume and change where real market data should appear.
    """
    sample = []
    for r in rows or []:
        n = r.get("netuid")
        if n is None:
            n = r.get("id")
        try:
            if n is not None and int(n) > 0:
                sample.append(r)
        except (TypeError, ValueError):
            continue
        if len(sample) >= 20:
            break
    if not sample:
        return False
    lacking = 0
    has_price = 0
    for r in sample:
        if r.get("price") in (None, "", 0, 0.0):
            continue
        has_price += 1
        vol = r.get("volume")
        chg = r.get("price_change_24h")
        if vol in (None, "", 0, 0.0) and chg in (None, "", 0, 0.0):
            lacking += 1
    if has_price == 0:
        return False
    return lacking >= max(1, (has_price + 1) // 2)


def _overlay_market_fields(base: List[Dict], market: List[Dict]) -> List[Dict]:
    """Copy TMC price/volume/chg onto registry/chain rows; append TMC-only netuids."""
    by_netuid: Dict[int, Dict] = {}
    for s in market or []:
        try:
            n = int(s.get("netuid"))
        except (TypeError, ValueError):
            continue
        by_netuid[n] = s

    out: List[Dict] = []
    seen = set()
    for row in base or []:
        merged = dict(row)
        raw_n = merged.get("netuid")
        if raw_n is None:
            raw_n = merged.get("id")
        try:
            n = int(raw_n) if raw_n is not None else None
        except (TypeError, ValueError):
            n = None
        if n is not None:
            merged["netuid"] = n
            seen.add(n)
            m = by_netuid.get(n)
            if m:
                for f in (
                    "price", "volume", "market_cap",
                    "price_change_24h", "price_change_7d", "price_change_30d",
                    "marketcap_rank", "symbol", "emission",
                ):
                    if m.get(f) is not None:
                        merged[f] = m[f]
                # Names: canonical resolver (taostat/registry beats TMC)
                try:
                    from internal.subnet_names import enrich_subnet_row
                    merged = enrich_subnet_row(merged, tmc_name=m.get("name"), use_taostats=False)
                except Exception:
                    if m.get("name") and not merged.get("name"):
                        merged["name"] = m["name"]
                if not merged.get("source"):
                    merged["source"] = "taomarketcap"
                merged["market_live"] = True
        out.append(merged)

    for n, m in by_netuid.items():
        if n not in seen:
            out.append(dict(m))
    return out


def get_all_subnets() -> List[Dict]:
    """Return all subnets with market fields when possible.

    Prefer the live on-chain feed when it already has prices. Otherwise overlay
    TaoMarketCap market data (or use TMC alone) so picks are not stuck on a
    registry snapshot without price/volume. See docs/EXTREME_AUDIT.md #1.
    """
    live: List[Dict] = []
    try:
        from internal.live_subnets import get_live_subnets

        live = get_live_subnets() or []
    except Exception as exc:  # pragma: no cover - defensive
        logger.warning("Live subnet feed unavailable, using TaoMarketCap: %s", exc)

    if live and _rows_have_market_fields(live):
        if not _rows_missing_market_values(live):
            return live
        # Live rows carry price but lack volume/change — overlay TMC market data.
        try:
            tmc = _get_all_subnets_tao()
        except Exception as exc:  # pragma: no cover - defensive
            logger.warning("TMC overlay unavailable for market backfill: %s", exc)
            tmc = None
        if tmc:
            return _overlay_market_fields(live, tmc)
        return live

    tmc = _get_all_subnets_tao()
    if tmc and live:
        return _overlay_market_fields(live, tmc)
    if tmc:
        return tmc
    return live


def _get_all_subnets_tao() -> List[Dict]:
    """Original TaoMarketCap implementation (cache + fallback)."""
    init_db()
    cached = get_cached("all_subnets")
    if cached:
        return cached.get("subnets", [])
    raw = fetch_all_subnets_from_api()
    if raw:
        set_cache("all_subnets", {"subnets": raw})
        return raw
    from fetchers._sqlite import db_conn

    with db_conn(DB_PATH) as conn:
        c = conn.cursor()
        c.execute("SELECT data FROM subnets_cache WHERE key = ?", ("all_subnets",))
        row = c.fetchone()
    if row:
        cached_data = json.loads(row[0]).get("subnets", [])
        if cached_data:
            logger.info("Returning %d subnets from stale cache", len(cached_data))
            return cached_data
    logger.warning("No cache available, returning static fallback")
    return []


def get_subnet_data(netuid: int) -> Optional[Dict]:
    """Get data for a single subnet by netuid."""
    subnets = get_all_subnets()
    for s in subnets:
        if s.get("netuid") == netuid:
            return s
    return None
